from pathlib import Path
import difflib,json,hashlib
out=Path(__file__).parent

def proposal(id,changes):
 p=Path('items')/(id+'.md');old=(out/'preimages'/p).read_text();new=old
 for a,b in changes:
  assert new.count(a)==1,(id,a,new.count(a));new=new.replace(a,b)
 new=new.replace(chr(92)+chr(39),chr(39))
 target=out/'proposals'/p;target.write_text(new)
 patch=''.join(difflib.unified_diff(old.splitlines(True),new.splitlines(True),fromfile='a/'+str(p),tofile='b/'+str(p)))
 (out/'proposals'/(id+'.patch')).write_text(patch)
 return {'id':id,'canonical_path':str(p),'before_raw_sha256':hashlib.sha256(old.encode()).hexdigest(),'proposal_path':str(target),'proposal_raw_sha256':hashlib.sha256(new.encode()).hexdigest(),'patch_path':str(out/'proposals'/(id+'.patch')),'applied':False,'verification_metadata':'Preserved only to show surgical content difference; future actual published correction needs root-owned genuine receipt/ledger/check bindings, never candidate audit reuse.'}

